               <p>Fresh merchandising for wardrobe, living, and gifting.</p>
             </div>
           </article>
           <article class="promo-item">
             <span class="promo-item-icon" aria-hidden="true">03</span>
             <div>
               <h2>Member pricing on signature lines</h2>
               <p>Unlock exclusive offers across best sellers and bundles.</p>
             </div>
           </article>
         </section>
       `;
     }

     function SectionHeader(id, title, copy, linkText) {
       return `
         <div class="section-header">
           <div>
             <h2 id="${id}">${title}</h2>
             <p>${copy}</p>
           </div>
           <a class="section-link" href="#top">${linkText}</a>
         </div>
       `;
     }

     function ProductCard(product) {
       return `
         <article class="product-card">
           <a class="product-link" href="#top">
             <div class="product-visual" aria-hidden="true" style="--card-gradient: ${product.gradient};"></div>
             <div class="card-body">
               <div class="card-meta">
                 <span class="kicker">${product.category}</span>
                 <span>${product.note}</span>
               </div>
               <div>
                 <h3>${product.name}</h3>
                 <p class="card-copy">${product.description}</p>
               </div>
               <div class="price-row">
                 <span class="price">${product.price}</span>
                 <span class="price-note">Limited run</span>
               </div>
             </div>
           </a>
           <div class="card-body" style="padding-top: 0;">
             <div class="card-actions">
               <button class="card-action card-action-primary" type="button" data-product="${product.name}" aria-label="${product.cta}: ${product.name}">
                 ${product.cta}
               </button>
               <a class="card-action" href="#editorial">Style notes</a>
             </div>
           </div>
         </article>
       `;
     }

     function DealCard(deal) {
       return `
         <article class="deal-card">
           <a class="deal-link" href="#top">
             <div class="deal-visual" aria-hidden="true" style="--card-gradient: ${deal.gradient};"></div>
             <div class="card-body">
               <div class="card-meta">
                 <span class="kicker">${deal.badge}</span>
                 <span>${deal.meta}</span>
               </div>
               <div>
                 <h3>${deal.name}</h3>
                 <p class="card-copy">${deal.description}</p>
               </div>
               <span class="section-link">${deal.linkText}</span>
             </div>
           </a>
         </article>
       `;
     }

     function StoryCard(story, extraClass) {
       return `
         <article class="story-card ${extraClass || ""}">
           <a class="story-link" href="#top">
             <div class="story-visual" aria-hidden="true" style="--card-gradient: ${story.gradient};"></div>
             <div class="card-body">
               <div class="card-meta">
                 <span class="kicker">${story.category}</span>
                 <span>${story.meta}</span>
               </div>
               <div>
                 <h3>${story.name}</h3>
                 <p class="card-copy">${story.description}</p>
               </div>
               <span class="section-link">Read story</span>
             </div>
           </a>
         </article>
       `;
     }

     function FeaturedSection() {
       return `
         <section class="section" id="featured-products" aria-labelledby="featured-heading">
           ${SectionHeader(
             "featured-heading",
             "Featured products",
             "Signature pieces and smart staples chosen to bring a premium feel to everyday shopping.",
             "Back to top"
           )}
           <div class="cards-grid">
             ${featuredProducts.map(ProductCard).join("")}
           </div>
           <p class="status" id="shopping-status" aria-live="polite"></p>
         </section>
       `;
     }

     function DealsSection() {
       return `
         <section class="section" id="deals" aria-labelledby="deals-heading">
           ${SectionHeader(
             "deals-heading",
             "Deals worth catching",
             "Clear, high-visibility promotions keep value front and center without disrupting the premium brand feel.",
             "Jump to top"
           )}
           <div class="cards-grid">
             ${deals.map(DealCard).join("")}
           </div>
         </section>
       `;
     }

     function EditorialSection() {
       return `
         <section class="section" id="editorial" aria-labelledby="editorial-heading">
           ${SectionHeader(
             "editorial-heading",
             "Editorial content",
             "Stories, guides, and behind-the-scenes features that add context and deepen the product experience.",
             "Return to top"
           )}
           <div class="editorial-layout">
             ${StoryCard(stories[0], "feature-story")}
             <div class="story-stack">
               ${StoryCard(stories[1], "")}
               <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
                 <h2 id="newsletter-heading">Get the weekly retail edit</h2>
                 <p>Product launches, styling notes, and member-only offers in one concise email.</p>
                 <form>
                   <div class="field">
                     <label for="email">Email address</label>
                     <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" aria-describedby="email-help">
                     <span class="field-help" id="email-help">We send one message a week, plus limited collection alerts.</span>
                   </div>
                   <button class="button" type="submit">Join the list</button>
                 </form>
               </section>
               ${StoryCard(stories[2], "")}
