       `;
     }

     function Footer() {
       return `
         <footer class="site-footer">
           <div class="footer-card">
             <div>
               <strong>Northstar Retail</strong>
               <p>Modern essentials for wardrobe, home, and gifting.</p>
             </div>
             <nav class="footer-nav" aria-label="Footer">
               <ul>
                 <li><a href="#featured-products">Shop</a></li>
                 <li><a href="#deals">Offers</a></li>
                 <li><a href="#editorial">Journal</a></li>
               </ul>
             </nav>
           </div>
         </footer>
       `;
     }

     function App() {
       return `
         <div id="top">
           ${Header()}
           <main id="maincontent" tabindex="-1">
             ${Hero()}
             ${PromoStrip()}
             ${FeaturedSection()}
             ${DealsSection()}
             ${EditorialSection()}
           </main>
           ${Footer()}
         </div>
       `;
     }

     document.getElementById("app").innerHTML = App();

     document.addEventListener("click", (event) => {
       const button = event.target.closest("[data-product]");
       if (!button) {
         return;
       }

       const status = document.getElementById("shopping-status");
       status.textContent = button.dataset.product + " added to bag.";
     });

     document.addEventListener("submit", (event) => {
       if (!(event.target instanceof HTMLFormElement)) {
         return;
       }

       event.preventDefault();
       const status = document.getElementById("shopping-status");
       status.textContent = "Thanks for joining the weekly retail edit.";
     });
   </script>
 </body>
 </html>

')
